// ESP32 OTA + Blink
#include <WiFi.h>
#include <ArduinoOTA.h>

const char* ssid     = "DEIN_WLAN";
const char* password = "DEIN_PASSWORT";

#define LED_PIN 2

void setup() {
  Serial.begin(115200);
  pinMode(LED_PIN, OUTPUT);

  WiFi.mode(WIFI_STA);
  WiFi.begin(ssid, password);
  Serial.print("Verbinde");
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  Serial.println();
  Serial.print("IP: ");
  Serial.println(WiFi.localIP());

  ArduinoOTA.setHostname("microlearn-esp32");
  ArduinoOTA.setPassword("microlearn");

  ArduinoOTA.onStart([]() {
    Serial.println("OTA Start");
  });
  ArduinoOTA.onEnd([]() {
    Serial.println("\nOTA Ende — Neustart...");
  });
  ArduinoOTA.onError([](ota_error_t error) {
    Serial.printf("OTA Fehler [%u]\n", error);
  });

  ArduinoOTA.begin();
  Serial.println("OTA bereit");
}

void loop() {
  ArduinoOTA.handle();

  digitalWrite(LED_PIN, HIGH);
  delay(500);
  digitalWrite(LED_PIN, LOW);
  delay(500);
}
